RAJ_STRONG = ['राजस्थान', 'जयपुर', 'मेवाड़', 'मारवाड़', 'शेखावाटी', 'हड़ौती', 'बीकानेर', 'जोधपुर', 'उदयपुर', 'जैसलमेर', 'अजमेर', 'राजस्थानी', 'अरावली', 'थार', 'सांभर', 'चंबल', 'बनास', 'महाराणा', 'राजसमंद', 'नाथद्वारा', 'माउंट आबू', 'पश्चिमी राजस्थान']

def classify(text, opts=None):
    t = (text or '') + ' ' + ' '.join(opts or [])
    scores = {s: 0 for s in KEYWORDS}
    for subj, kws in KEYWORDS.items():
        for kw in kws:
            if kw in t:
                scores[subj] += 1
    # strong Rajasthan markers dominate
    for kw in RAJ_STRONG:
        if kw in t:
            scores['raj-gk'] += 2
    best = max(scores, key=scores.get)
    if scores[best] == 0:
        return 'india-gk', 0.0
    srt = sorted(scores.values(), reverse=True)
    conf = 1.0 if len(srt) == 1 or srt[0] >= srt[1] + 2 else 0.5
    return best, conf

if __name__ == '__main__':
    # validation against police wave tags
    import json, re, sys
    sys.path.insert(0, '.')
    from gather.subject_classifier import classify
    d = open('app/src/data/bank/pyq-police-2022.js', encoding='utf-8').read()
    recs = re.findall(r'"subject": "(\w[\w-]*)",.*?"hi": "((?:[^"\\]|\\.)*)"', d, re.S)
    ok, tot, lowconf_wrong = 0, 0, []
    per_subj = {}
    for subj, hi in recs:
        pred, conf = classify(hi)
        tot += 1
        per_subj.setdefault(subj, [0,0])
        per_subj[subj][1] += 1
        if pred == subj:
            ok += 1; per_subj[subj][0] += 1
        elif conf >= 1.0:
            lowconf_wrong.append((subj, pred, hi[:60]))
    print(f'accuracy: {ok}/{tot} = {ok/tot*100:.1f}%')
    for s,(c,t) in sorted(per_subj.items()):
        print(f'  {s}: {c}/{t} = {c/t*100:.0f}%')
    print('high-conf wrong (sample):')
    for x in lowconf_wrong[:8]: print('  ', x[0], '->', x[1], '|', x[2])
